//! Phoneme Discrimination (Categorical Perception).
//!
//! Phonemes along an acoustic continuum are perceived categorically — changes
//! within a category are hard to detect, while changes that cross a category
//! boundary are easy. This tests the brain's categorical encoding of continuous
//! sensory input.
//!
//! HDC implementation: A phoneme continuum is generated by interpolating between
//! two endpoint HVs (/ba/ to /pa/). Category prototypes are defined at each end.
//! Pairs of stimuli are presented for same/different judgments. Within-category
//! pairs (both /ba/ or both /pa/) are hard despite physical difference;
//! cross-boundary pairs (one /ba/, one /pa/) are easy.
//!
//! Human baselines (Liberman et al., 1957; Eimas et al., 1971):
//! - cross_boundary_accuracy: 0.90 (SD≈0.05)
//! - within_category_accuracy: 0.55 (SD≈0.08) — near chance
//! - categorical_perception_index: 0.35 (SD≈0.10) — cross minus within
//! - boundary_sharpness: 0.75 (SD≈0.10) — steepness of identification at boundary

use crate::harness::config::BenchmarkConfig;
use crate::harness::difficulty::difficulty_model_for;
use crate::harness::report::{BenchmarkResult, MetricValue};
use crate::harness::trial_analysis::TrialOutcome;
use crate::harness::{BenchmarkProvenance, PsychBenchmark};
use std::collections::BTreeMap;
use symthaea_core::hdc::ContinuousHV;

/// Phoneme Discrimination benchmark.
pub struct PhonemeDiscriminationBenchmark;

struct TrialResult {
    cross_boundary_accuracy: f64,
    within_category_accuracy: f64,
    categorical_perception_index: f64,
    boundary_sharpness: f64,
    rt_ticks: f64,
}

impl PhonemeDiscriminationBenchmark {
    fn run_trial(&self, config: &BenchmarkConfig, trial_idx: usize) -> TrialResult {
        let dim = config.dimension;
        let seed = config.trial_seed("speech", "phoneme_discrimination", trial_idx);
        let mut rng = seed ^ 0x9E3779B97F4A7C15;

        let xor_shift = |s: &mut u64| {
            *s ^= *s << 13;
            *s ^= *s >> 7;
            *s ^= *s << 17;
        };

        // Endpoint phoneme HVs: /ba/ and /pa/
        let endpoint_ba = ContinuousHV::random(dim, seed.wrapping_add(100)).normalize();
        let endpoint_pa = ContinuousHV::random(dim, seed.wrapping_add(200)).normalize();

        // Create continuum: n_steps positions from /ba/ to /pa/
        let n_steps = 10;
        let continuum: Vec<ContinuousHV> = (0..=n_steps)
            .map(|i| {
                let t = i as f32 / n_steps as f32;
                ContinuousHV::weighted_bundle(&[&endpoint_ba, &endpoint_pa], &[1.0 - t, t])
                    .normalize()
            })
            .collect();

        // Category boundary at midpoint
        let boundary_idx = n_steps / 2;

        // Category prototypes: averages of each half
        let ba_proto = ContinuousHV::weighted_bundle(
            &[&continuum[0], &continuum[1], &continuum[2]],
            &[0.5, 0.3, 0.2],
        )
        .normalize();
        let pa_proto = ContinuousHV::weighted_bundle(
            &[
                &continuum[n_steps],
                &continuum[n_steps - 1],
                &continuum[n_steps - 2],
            ],
            &[0.5, 0.3, 0.2],
        )
        .normalize();

        // Difficulty and time pressure modulation
        let diff_model = difficulty_model_for(self.name());
        let tp_noise: f32 = (0.08 + config.time_pressure as f32 * 0.10)
            / diff_model.signal_multiplier(config.difficulty) as f32;
        let noise_degrade = config.effective_noise() as f32 * 0.30;

        // Discrimination task: present pairs and judge same/different
        let step_diff = 2; // pairs separated by 2 steps on the continuum
        let mut cross_correct = 0u32;
        let mut cross_total = 0u32;
        let mut within_correct = 0u32;
        let mut within_total = 0u32;
        let mut rt_sum = 0.0f64;
        let mut rt_count = 0u32;

        // Identification function for boundary sharpness
        let mut identifications: Vec<(f64, f64)> = Vec::new();

        for i in 0..=n_steps {
            // Identification: classify each continuum position as /ba/ or /pa/
            let sim_ba = continuum[i].similarity(&ba_proto) * (1.0 - noise_degrade);
            let sim_pa = continuum[i].similarity(&pa_proto) * (1.0 - noise_degrade);
            let pa_proportion = (sim_pa / (sim_ba + sim_pa + 1e-8)) as f64;
            identifications.push((i as f64 / n_steps as f64, pa_proportion));

            // Discrimination pairs: compare stimulus i with stimulus i+step_diff
            if i + step_diff <= n_steps {
                let stim_1 = &continuum[i];
                let stim_2 = &continuum[i + step_diff];

                // Is this pair cross-boundary?
                let crosses_boundary = (i < boundary_idx && i + step_diff >= boundary_idx)
                    || (i >= boundary_idx && i + step_diff < boundary_idx);

                // Physical difference: similarity between the two stimuli
                let physical_sim = stim_1.similarity(stim_2) * (1.0 - noise_degrade);

                // Categorical encoding: each stimulus is encoded relative to prototypes
                let s1_ba = stim_1.similarity(&ba_proto) * (1.0 - noise_degrade);
                let s1_pa = stim_1.similarity(&pa_proto) * (1.0 - noise_degrade);
                let s2_ba = stim_2.similarity(&ba_proto) * (1.0 - noise_degrade);
                let s2_pa = stim_2.similarity(&pa_proto) * (1.0 - noise_degrade);

                // Category assignment: which prototype is closer?
                let s1_category = if s1_ba > s1_pa { 0 } else { 1 };
                let s2_category = if s2_ba > s2_pa { 0 } else { 1 };

                // Discrimination evidence: physical difference + categorical difference
                // Cross-boundary pairs get a categorical boost; within-category pairs
                // rely only on (weak) physical difference
                let categorical_diff = if s1_category != s2_category {
                    0.3 // categorical boundary crossing amplifies perceived difference
                } else {
                    0.0
                };

                // The stimuli ARE different (step_diff > 0), so "different" is correct
                let evidence_different = (1.0 - physical_sim) + categorical_diff;

                // Decision with noise
                let n_presentations = 5;
                let mut pair_correct = 0u32;

                for _ in 0..n_presentations {
                    xor_shift(&mut rng);
                    let noise = ((rng % 10000) as f32 / 10000.0 - 0.5)
                        * tp_noise
                        * diff_model.temperature_multiplier(config.difficulty) as f32;

                    // Threshold for "different" response
                    let threshold = 0.25;
                    if evidence_different + noise > threshold {
                        pair_correct += 1;
                    }

                    // RT: cross-boundary is faster (categorical pop-out)
                    let base_rt = if crosses_boundary { 3.5 } else { 5.0 };
                    let tp_speedup = config.time_pressure * 1.0;
                    rt_sum += (base_rt - tp_speedup).max(1.0);
                    rt_count += 1;
                }

                let pair_accuracy = pair_correct as f64 / n_presentations as f64;

                if crosses_boundary {
                    cross_correct += pair_correct;
                    cross_total += n_presentations as u32;
                } else {
                    within_correct += pair_correct;
                    within_total += n_presentations as u32;
                }

                let _ = pair_accuracy;
            }
        }

        let cross_acc = if cross_total > 0 {
            cross_correct as f64 / cross_total as f64
        } else {
            0.5
        };
        let within_acc = if within_total > 0 {
            within_correct as f64 / within_total as f64
        } else {
            0.5
        };
        let cpi = (cross_acc - within_acc).max(0.0);

        // Boundary sharpness: steepness of identification function at the boundary
        // Measured as maximum slope of the identification curve near the boundary
        let mut max_slope = 0.0f64;
        for i in 1..identifications.len() {
            let delta_id = (identifications[i].1 - identifications[i - 1].1).abs();
            let delta_pos = identifications[i].0 - identifications[i - 1].0;
            if delta_pos > 0.0 {
                let slope = delta_id / delta_pos;
                if slope > max_slope {
                    max_slope = slope;
                }
            }
        }
        // Normalize: perfect step function would have slope = n_steps at boundary
        let boundary_sharpness = (max_slope / n_steps as f64).clamp(0.0, 1.0);

        let mean_rt = if rt_count > 0 {
            rt_sum / rt_count as f64
        } else {
            4.0
        };

        TrialResult {
            cross_boundary_accuracy: cross_acc,
            within_category_accuracy: within_acc,
            categorical_perception_index: cpi,
            boundary_sharpness,
            rt_ticks: mean_rt,
        }
    }
}

impl PsychBenchmark for PhonemeDiscriminationBenchmark {
    fn name(&self) -> &str {
        "Speech::PhonemeDiscrimination"
    }

    fn provenance(&self) -> Option<BenchmarkProvenance> {
        Some(BenchmarkProvenance {
            paradigm: "Categorical Perception of Phonemes",
            citation: "Liberman et al. (1957)",
            year: 1957,
            doi: Some("10.1037/h0041882"),
        })
    }

    fn run(&self, config: &BenchmarkConfig) -> BenchmarkResult {
        let start = std::time::Instant::now();
        let mut result = BenchmarkResult::new(self.name(), config.label.clone());
        let mut trace = Vec::new();

        let mut cross_accs = Vec::new();
        let mut within_accs = Vec::new();
        let mut cpis = Vec::new();
        let mut sharpnesses = Vec::new();
        let mut rts = Vec::new();

        for trial in 0..config.trials_per_condition {
            let r = self.run_trial(config, trial);
            cross_accs.push(r.cross_boundary_accuracy);
            within_accs.push(r.within_category_accuracy);
            cpis.push(r.categorical_perception_index);
            sharpnesses.push(r.boundary_sharpness);
            rts.push(r.rt_ticks);
            if config.trial_trace {
                trace.push(TrialOutcome {
                    trial_idx: trace.len(),
                    condition: "phoneme_discrimination".to_string(),
                    correct: r.categorical_perception_index > 0.1,
                    rt_ticks: r.rt_ticks,
                    similarity: 0.0,
                    confidence: 0.0,
                    response_idx: 0,
                    extra: BTreeMap::new(),
                });
            }
        }

        result.insert(
            "cross_boundary_accuracy",
            MetricValue::from_samples(&cross_accs),
        );
        result.insert(
            "within_category_accuracy",
            MetricValue::from_samples(&within_accs),
        );
        result.insert(
            "categorical_perception_index",
            MetricValue::from_samples(&cpis),
        );
        result.insert(
            "boundary_sharpness",
            MetricValue::from_samples(&sharpnesses),
        );
        result.insert("rt_ticks", MetricValue::from_samples(&rts));

        result.conditions = 2; // within-category vs cross-boundary
        result.trials_per_condition = config.trials_per_condition;
        if config.trial_trace {
            result.trial_trace = trace;
        }
        result.elapsed_ms = start.elapsed().as_millis() as u64;
        result
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_phoneme_discrimination_runs() {
        let config = BenchmarkConfig {
            dimension: 256,
            trials_per_condition: 3,
            ..Default::default()
        };
        let result = PhonemeDiscriminationBenchmark.run(&config);
        assert!(result.metrics.contains_key("cross_boundary_accuracy"));
        assert!(result.metrics.contains_key("within_category_accuracy"));
        assert!(result.metrics.contains_key("categorical_perception_index"));
        assert!(result.metrics.contains_key("boundary_sharpness"));
    }

    #[test]
    fn test_phoneme_discrimination_finite_metrics() {
        let config = BenchmarkConfig {
            dimension: 128,
            trials_per_condition: 5,
            ..Default::default()
        };
        let result = PhonemeDiscriminationBenchmark.run(&config);
        for (key, val) in &result.metrics {
            assert!(val.mean.is_finite(), "metric {} is not finite", key);
        }
    }

    #[test]
    fn test_phoneme_discrimination_key_metric_bounded() {
        let config = BenchmarkConfig {
            dimension: 512,
            trials_per_condition: 10,
            ..Default::default()
        };
        let result = PhonemeDiscriminationBenchmark.run(&config);
        let cross = result.metrics["cross_boundary_accuracy"].mean;
        assert!(
            cross >= 0.0 && cross <= 1.0,
            "cross_boundary_accuracy ({:.3}) out of bounds",
            cross
        );
        let within = result.metrics["within_category_accuracy"].mean;
        assert!(
            within >= 0.0 && within <= 1.0,
            "within_category_accuracy ({:.3}) out of bounds",
            within
        );
        let cpi = result.metrics["categorical_perception_index"].mean;
        assert!(
            cpi >= 0.0 && cpi <= 1.0,
            "categorical_perception_index ({:.3}) out of bounds",
            cpi
        );
    }

    #[test]
    fn test_phoneme_discrimination_time_pressure() {
        let base = BenchmarkConfig {
            dimension: 512,
            trials_per_condition: 10,
            time_pressure: 0.0,
            ..Default::default()
        };
        let pressed = BenchmarkConfig {
            time_pressure: 1.0,
            ..base.clone()
        };
        let r_base = PhonemeDiscriminationBenchmark.run(&base);
        let r_press = PhonemeDiscriminationBenchmark.run(&pressed);
        // Under time pressure, RT should decrease
        let rt_base = r_base.metrics["rt_ticks"].mean;
        let rt_press = r_press.metrics["rt_ticks"].mean;
        assert!(
            rt_press <= rt_base + 0.5,
            "time pressure should reduce or maintain RT: base={:.2}, pressed={:.2}",
            rt_base,
            rt_press
        );
    }
}
